(() => {
return [...document.querySelectorAll("[data-audit=light]")].every(el => { const surface=el;
const rgba=v=>{const n=v.match(/[\d.]+/g);return [Number(n[0]),Number(n[1]),Number(n[2]),n.length>3?Number(n[3]):1]};
let bg=[255,255,255],nodes=[];for(let p=surface;p;p=p.parentElement)nodes.unshift(p);
for(const p of nodes){const c=rgba(getComputedStyle(p).backgroundColor);bg=bg.map((v,i)=>c[i]*c[3]+v*(1-c[3]))}
const lum=c=>c.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);
const a=lum(rgba(getComputedStyle(el).color).slice(0,3)),b=lum(bg);return(Math.max(a,b)+.05)/(Math.min(a,b)+.05)>=4.5;
});})()

